# Load the session data to see what demonstration pairs we have
import os, glob, re

def load():
    d = os.environ['RLM_SESSION_DIR']
    session_file = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'
    t = open(session_file).read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load()
print("Demographic pairs found:", sorted(G.keys()))
for k, v in G.items():
    if k != "Test input":
        print(f"\n=== {k}: {len(v)}x{len(v[0]) if v else 0} ===")
        print(v[:3])

